        observation?.invalidate()
        observation = nil
        pendingDownTimer?.invalidate()
        pendingUpTimer?.invalidate()
        if let observer = interruptionObserver {
            NotificationCenter.default.removeObserver(observer)
            interruptionObserver = nil
        }
